  const note = typeof body.note === 'string' ? body.note.trim() : '';
  const tags = cleanTags(body.tags);
  const now = new Date().toISOString();

  const result = stmts.insertBookmark.run({
    url: parsed.url,
    urlNorm: parsed.urlNorm,
    title,
    note,
    now,
